# the betting window again, closer: the visitor's blank card big on the counter (lower half), the four AIs' blank cards pinned behind the grille (upper half)
K="Same place and same art style as the reference picture, but a closer camera, seen squarely head-on: the upper half is the iron grille with four blank black cards with thin gold borders pinned in one row behind it, each card upright and flat to the viewer, nothing on them; the lower half is the dark counter with one large blank black card with a thin gold border lying flat in the middle, almost as wide as half the picture, nothing on it; to the right of that card two rubber stamps standing upright, one with a green handle, one with a red handle. One lamp above. No text, no letters, no numbers, no logos, no signs."
j(){ python3 -c 'import json,sys;print(json.dumps({"prompt":sys.argv[1],"aspect_ratio":sys.argv[2],"resolution":"1K","quality":"medium","output_format":"png","num_outputs":1}))' "$1" "$2"; }
python3 hd.py win2-n gpt-image-2 "$(j "$K Heavy brush and ink, dry brush, cross-hatching, ink splatter, black ink and grey wash, light in spot gold only. Not rendered." 3:4)" img/win-n.jpg > log-win2-n.txt 2>&1 &
python3 hd.py win2-l gpt-image-2 "$(j "$K Flat graphic badge style: pure black ground, flat solid cream, gold, green and red shapes only, hard straight edges, no texture, no gradients." 3:4)" img/win-l.jpg > log-win2-l.txt 2>&1 &
python3 hd.py win2-n-w gpt-image-2 "$(j "$K Heavy brush and ink, dry brush, cross-hatching, ink splatter, black ink and grey wash, light in spot gold only. Not rendered." 16:9)" img/win-n.jpg > log-win2-n-w.txt 2>&1 &
python3 hd.py win2-l-w gpt-image-2 "$(j "$K Flat graphic badge style: pure black ground, flat solid cream, gold, green and red shapes only, hard straight edges, no texture, no gradients." 16:9)" img/win-l.jpg > log-win2-l-w.txt 2>&1 &
wait
